<template>
  <div class="app-shell"><header class="topbar"><BrandLogo compact /><nav><RouterLink to="/">秒杀广场</RouterLink><RouterLink to="/orders">我的订单</RouterLink></nav><div class="user-area"><span class="avatar">{{ userInitial }}</span><span>{{ user.username || '用户' }}</span><button type="button" @click="handleLogout">退出</button></div></header>
    <main class="detail-content"><button class="back-button" type="button" @click="router.back()"><svg viewBox="0 0 24 24" fill="none"><path d="m15 18-6-6 6-6" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>返回秒杀广场</button>
      <p v-if="errorMessage" class="page-error">{{ errorMessage }} <button type="button" @click="loadDetail">重新加载</button></p>
      <div v-if="loading" class="detail-skeleton"><div></div><section><i></i><i></i><i></i></section></div>
      <section v-else-if="product" class="detail-card"><div class="detail-image"><img v-if="product.imageUrl" :src="product.imageUrl" :alt="product.productName"><span v-else>⚡</span></div><div class="detail-info"><span class="detail-kicker">{{ activity ? activityLabel(activity) : '精选商品' }}</span><h1>{{ product.productName }}</h1><p class="description">{{ product.description || '限时精选商品，数量有限，先到先得。' }}</p><div class="price-block"><strong>¥{{ formatPrice(activity?.seckillPrice || product.seckillPrice || product.price) }}</strong><del v-if="product.price">¥{{ formatPrice(product.price) }}</del><span>剩余 {{ activity?.remainingLimit ?? product.availableStock ?? '--' }} 件</span></div><div v-if="activity" class="activity-panel"><div><span>活动时间</span><b>{{ formatDate(activity.startTime) }} - {{ formatDate(activity.endTime) }}</b></div><div><span>每人限购</span><b>{{ activity.perUserLimit || 1 }} 件</b></div><div><span>活动状态</span><b class="active-text">{{ activityLabel(activity) }}</b></div></div><button class="seckill-button" type="button" :disabled="!canSeckill || submitting" @click="handleSeckill"><span v-if="submitting" class="spinner"></span>{{ submitting ? '正在排队...' : buttonText }}<svg v-if="!submitting" viewBox="0 0 24 24" fill="none"><path d="m9 18 6-6-6-6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></button><p v-if="submitError" class="submit-error">{{ submitError }}</p></div></section>
      <section v-else class="empty-card"><div class="empty-icon">🛍️</div><h3>商品不存在</h3><p>该商品可能已下架或暂时无法查看。</p></section>
    </main>
    <Transition name="modal"><div v-if="result" class="modal-backdrop" @click.self="result = null"><div class="result-modal"><span class="result-icon" :class="result.status === 1 ? 'success' : 'pending'">{{ result.status === 1 ? '✓' : '…' }}</span><h2>{{ result.status === 1 ? '抢购成功' : '正在排队' }}</h2><p>{{ result.status === 1 ? `订单号：${result.orderNo || '生成中'}` : '订单正在异步创建，请稍候查看订单状态。' }}</p><button type="button" @click="result.status === 1 ? router.push('/orders') : result = null">{{ result.status === 1 ? '查看订单' : '知道了' }}</button></div></div></Transition>
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import BrandLogo from '../components/BrandLogo.vue'
import { getSeckillPage } from '../api/activity'
import { getProduct } from '../api/product'
import { executeSeckill, getSeckillResult } from '../api/seckill'
import { logout } from '../api/auth'
import { clearSession, getCurrentUser } from '../utils/auth'

const route = useRoute(); const router = useRouter(); const user = getCurrentUser(); const userInitial = computed(() => (user.username || 'U').slice(0, 1).toUpperCase())
const product = ref(null); const activity = ref(null); const loading = ref(true); const submitting = ref(false); const errorMessage = ref(''); const submitError = ref(''); const result = ref(null); let pollTimer
const canSeckill = computed(() => activity.value?.status === 1 && Boolean(user.userId)); const buttonText = computed(() => activity.value?.status === 1 ? '立即抢购' : activity.value?.status === 0 ? '尚未开始' : activity.value ? '活动已结束' : '暂无活动')
function formatPrice(value) { return Number(value || 0).toFixed(2) }
function formatDate(value) { return value ? String(value).replace('T', ' ').slice(0, 16) : '--' }
function activityLabel(value) { return value?.status === 1 ? '进行中' : value?.status === 0 ? '即将开始' : '已结束' }
async function loadDetail() { loading.value = true; errorMessage.value = ''; try { if (route.query.activityId) { const response = await getSeckillPage(route.query.activityId); product.value = response.data?.product; activity.value = response.data?.activity } else { const response = await getProduct(route.params.id); product.value = response.data } } catch (error) { errorMessage.value = error.message } finally { loading.value = false } }
async function handleSeckill() { if (!canSeckill.value || submitting.value) return; submitError.value = ''; submitting.value = true; try { const response = await executeSeckill({ activityId: activity.value.id, userId: user.userId }); result.value = response.data; if (result.value?.status === 0 && result.value.seckillLogId) pollResult(result.value.seckillLogId) } catch (error) { submitError.value = error.message } finally { submitting.value = false } }
function pollResult(logId) { let count = 0; pollTimer = window.setInterval(async () => { count += 1; try { const response = await getSeckillResult(logId); result.value = response.data; if (response.data?.status !== 0 || count >= 10) { window.clearInterval(pollTimer); if (response.data?.status === 0) result.value = { ...response.data, status: 2, failReason: '订单处理超时，请稍后在订单页查看' } } } catch { if (count >= 10) window.clearInterval(pollTimer) } }, 1500) }
async function handleLogout() { try { await logout() } catch {} clearSession(); await router.replace('/login') }
onMounted(loadDetail); onBeforeUnmount(() => window.clearInterval(pollTimer))
</script>

<style scoped>
.app-shell{min-height:100vh;background:#f5f8fc}.topbar{position:sticky;z-index:10;top:0;display:flex;height:68px;padding:0 max(24px,calc((100vw - 1180px)/2));align-items:center;gap:54px;border-bottom:1px solid #e8edf5;background:rgba(255,255,255,.92);backdrop-filter:blur(12px)}nav{display:flex;align-self:stretch;gap:32px}nav a{position:relative;display:flex;align-items:center;color:var(--text-muted);font-size:14px;text-decoration:none}nav a.router-link-active{color:var(--primary);font-weight:650}nav a.router-link-active::after{content:'';position:absolute;right:0;bottom:-1px;left:0;height:2px;border-radius:4px;background:var(--primary)}.user-area{display:flex;margin-left:auto;align-items:center;gap:9px;color:#526078;font-size:13px}.avatar{display:grid;width:34px;height:34px;place-items:center;border-radius:50%;color:#fff;font-weight:700;background:linear-gradient(145deg,#66a0f7,#3476de)}.user-area button{margin-left:8px;padding:6px 10px;border:0;color:#8b99ad;background:none;cursor:pointer}.detail-content{max-width:1080px;margin:0 auto;padding:35px 24px 72px}.back-button{display:inline-flex;margin-bottom:22px;align-items:center;gap:5px;padding:0;border:0;color:#718198;font:inherit;font-size:13px;background:none;cursor:pointer}.back-button:hover{color:var(--primary)}.back-button svg{width:18px}.detail-card{display:grid;grid-template-columns:48% 52%;overflow:hidden;border:1px solid #e4ebf4;border-radius:20px;background:#fff;box-shadow:0 8px 25px rgba(37,67,108,.05)}.detail-image{display:grid;min-height:520px;place-items:center;overflow:hidden;background:linear-gradient(145deg,#edf5ff,#dfeeff)}.detail-image img{width:100%;height:100%;object-fit:cover}.detail-image span{font-size:90px;filter:drop-shadow(0 15px 20px rgba(47,114,231,.2))}.detail-info{padding:54px 54px 45px}.detail-kicker{display:inline-block;padding:5px 9px;border-radius:6px;color:#2864c7;font-size:11px;background:#edf4ff}.detail-info h1{margin:18px 0 12px;color:var(--text-strong);font-size:32px;letter-spacing:-.8px}.description{margin:0 0 28px;color:#8291a6;font-size:14px;line-height:1.8}.price-block{display:flex;align-items:baseline;gap:10px;padding-bottom:25px;border-bottom:1px solid #edf0f4}.price-block strong{color:#ec5d65;font-size:34px}.price-block del{color:#adb7c4;font-size:13px}.price-block span{margin-left:auto;color:#9caabd;font-size:12px}.activity-panel{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:10px;padding:23px 0}.activity-panel div{display:flex;flex-direction:column;gap:8px}.activity-panel span{color:#a0acbc;font-size:11px}.activity-panel b{color:#52637a;font-size:12px;font-weight:600;line-height:1.4}.activity-panel .active-text{color:#3caf79}.seckill-button{display:flex;width:100%;height:51px;align-items:center;justify-content:center;gap:8px;margin-top:18px;border:0;border-radius:11px;color:#fff;font:inherit;font-size:15px;font-weight:650;background:linear-gradient(115deg,#2c70e9,#4388f3);box-shadow:0 10px 22px rgba(44,112,233,.2);cursor:pointer}.seckill-button:disabled{cursor:not-allowed;opacity:.52;box-shadow:none}.seckill-button svg{width:19px}.submit-error{margin:13px 0 0;padding:10px 12px;border-radius:8px;color:#b43d3d;font-size:12px;background:#fff1f1}.page-error{padding:11px 13px;border-radius:9px;color:#b44d4d;font-size:13px;background:#fff2f2}.page-error button{margin-left:8px;padding:0;border:0;color:#c33f3f;text-decoration:underline;background:none;cursor:pointer}.empty-card{padding:65px 24px;border:1px solid #e7edf5;border-radius:18px;text-align:center;background:#fff}.empty-icon{display:grid;width:60px;height:60px;margin:0 auto 18px;place-items:center;border-radius:18px;font-size:27px;background:var(--primary-soft)}.empty-card h3{margin:0 0 9px;color:#34425a;font-size:17px}.empty-card p{margin:0;color:var(--text-light);font-size:13px}.detail-skeleton{display:grid;grid-template-columns:48% 52%;height:520px;overflow:hidden;border-radius:20px;background:#fff}.detail-skeleton>div{background:#edf2f8}.detail-skeleton section{padding:55px}.detail-skeleton i{display:block;width:80%;height:25px;margin:20px 0;border-radius:6px;background:#edf2f8}.detail-skeleton i:first-child{width:35%;height:17px}.modal-backdrop{position:fixed;z-index:30;inset:0;display:grid;place-items:center;padding:20px;background:rgba(19,35,61,.35);backdrop-filter:blur(3px)}.result-modal{width:min(380px,100%);padding:38px 30px 30px;border-radius:18px;text-align:center;background:#fff;box-shadow:0 20px 55px rgba(25,46,80,.2)}.result-icon{display:grid;width:58px;height:58px;margin:0 auto 15px;place-items:center;border-radius:50%;color:#fff;font-size:29px;font-weight:700}.result-icon.success{background:#40bd81}.result-icon.pending{background:#6c9bec}.result-modal h2{margin:0 0 9px;color:#263650;font-size:21px}.result-modal p{margin:0 0 25px;color:#8593a6;font-size:13px}.result-modal button{width:100%;height:43px;border:0;border-radius:9px;color:#fff;font:inherit;font-size:13px;font-weight:650;background:var(--primary);cursor:pointer}.spinner{width:17px;height:17px;border:2px solid rgba(255,255,255,.45);border-top-color:#fff;border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.modal-enter-active,.modal-leave-active{transition:opacity .2s}.modal-enter-from,.modal-leave-to{opacity:0}@media(max-width:760px){nav{display:none}.topbar{padding:0 18px}.user-area>span:not(.avatar){display:none}.detail-content{padding:24px 16px}.detail-card,.detail-skeleton{grid-template-columns:1fr}.detail-image{min-height:300px;height:300px}.detail-info{padding:30px 24px}.detail-info h1{font-size:27px}.detail-skeleton{height:auto}.detail-skeleton>div{height:300px}.detail-skeleton section{padding:25px}.activity-panel{gap:8px}}
</style>
